cd /user/user1/autorlbench-runs/20261117151748-11809-12b9/workspace/results/run60 && python3 -I - <<'EOF'
import json
rows=[]
for line in open('metrics.jsonl'):
    d=json.loads(line); data=d.get('data',{})
    if 'critic/score/mean' in data:
        rows.append((d['step'],data['critic/score/mean'],data.get('response/aborted_ratio'),data.get('actor/entropy')))
import statistics
for s,v,a,e in rows: print(s, round(v,4))
# block means
for lo in range(0,60,10):
    blk=[v for s,v,_,_ in rows if lo< s <=lo+10]
    if blk: print(f"steps {lo+1}-{lo+10}: mean={statistics.mean(blk):.4f}")
EOF
echo ===; tail -40 train.log; echo ===; grep -inE "error|warn|exception|traceback|nan|oom|abort" train.log | head -30

